'use strict';
// Browser features are independent of the extractor version; remote features are capability-gated.
Object.assign(data,{notes:read('pt-notes',{}),progress:read('pt-progress',{}),queue:read('pt-queue',[])});
Object.assign(state,{source:localStorage.getItem('pt-source')||'youtube',services:[],apiVersion:2,filter:'',sort:'',player:null,loopA:null,loopB:null,autoNext:localStorage.getItem('pt-autonext')==='true',sleepUntil:0});
const sourceNames={youtube:'YouTube',soundcloud:'SoundCloud',bandcamp:'Bandcamp',peertube:'PeerTube',mediaccc:'media.ccc.de',local:'Local file',direct:'Direct media'};
let sessionMedia=null,blobUrl='',suggestTimer,progressSavedAt=0;
const stamp=n=>{n=Math.max(0,Math.floor(Number(n)||0));return n>=3600?`${Math.floor(n/3600)}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`:`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;};
function inferSource(url){try{const h=new URL(url).hostname;if(h==='youtube.com'||h.endsWith('.youtube.com')||h==='youtu.be')return 'youtube';if(h==='soundcloud.com'||h.endsWith('.soundcloud.com'))return 'soundcloud';if(h==='bandcamp.com'||h.endsWith('.bandcamp.com'))return 'bandcamp';if(h==='media.ccc.de')return 'mediaccc';if(h===new URL(state.services.find(s=>s.id==='peertube')?.baseUrl||'https://framatube.org').hostname)return 'peertube';}catch{}return null;}
function itemSource(v){return v.service||inferSource(v.url||v.id)||'youtube';}
function originalUrl(v){return safe(v.url)||(/^[\w-]{11}$/.test(v.id)?'https://www.youtube.com/watch?v='+v.id:'');}
function watchHash(v){return '#watch='+encodeURIComponent(v.id);}
function downloadable(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const baseKnown=known;
known=function(id){return baseKnown(id)||data.queue.find(v=>v.id===id)||(sessionMedia?.id===id?sessionMedia:null);};
card=function(v){const kind=v.kind||'video',href='#'+(kind==='channel'?'channel':kind==='remotePlaylist'?'remotePlaylist':'watch')+'='+encodeURIComponent(v.id||v.url);const stats=[v.views>=0?count(v.views)+' views':'',v.uploaded||''].filter(Boolean).join(' · ');return `<article class="card"><a class="thumbnail" href="${href}"><img src="${esc(safe(v.thumbnail))}" alt="" loading="lazy"><span class="duration">${esc(kind==='channel'?'Channel':kind==='remotePlaylist'?(v.streamCount||'')+' videos':v.duration||'Play')}</span></a><div class="cardbody">${avatar(v)}<div><h3><a href="${href}">${esc(v.title)}</a></h3><p>${v.channelUrl?`<a class="channel-link" href="#channel=${encodeURIComponent(v.channelUrl)}">${esc(v.channel)}</a>`:esc(v.channel)}${v.verified?' ✓':''}</p><p>${esc(stats)}</p><p class="carddesc">${esc(v.description||'')}</p></div></div>${kind==='video'?`<button class="icon cardmenu" data-save="${esc(v.id)}" aria-label="Save or queue ${esc(v.title)}">${icon('dots')}</button>`:''}</article>`;};
const oldRenderSave=renderSave;
renderSave=function(){oldRenderSave();const b=document.createElement('button');b.textContent='＋ Add to play queue';b.onclick=()=>enqueue(state.saveTarget);$('#playlistOptions').append(b);};
function enqueue(v){if(!v)return;if(!data.queue.some(x=>x.id===v.id))data.queue.push(v);persist();renderQueue();toast('Added to play queue');}
function renderQueue(){$('#queue').innerHTML=data.queue.length?data.queue.map((v,i)=>`<div class="queue-row ${v.id===state.current?.id?'current':''}"><a href="${watchHash(v)}"><small>${i+1}</small>${esc(v.title)}</a><button data-queue-up="${i}" aria-label="Move ${esc(v.title)} up" ${i===0?'disabled':''}>↑</button><button data-queue-remove="${i}" aria-label="Remove ${esc(v.title)}">×</button></div>`).join(''):'<p class="muted">Use a video’s menu to add it here.</p>';$('#queue').querySelectorAll('[data-queue-remove]').forEach(b=>b.onclick=()=>{data.queue.splice(Number(b.dataset.queueRemove),1);persist();renderQueue();});$('#queue').querySelectorAll('[data-queue-up]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.queueUp);[data.queue[i-1],data.queue[i]]=[data.queue[i],data.queue[i-1]];persist();renderQueue();});}
function nextInQueue(){if(!state.autoNext)return;const i=data.queue.findIndex(v=>v.id===state.current?.id);const n=data.queue[i>=0?i+1:0];if(n){state.autoStartTarget=n.id;location.hash=watchHash(n);}}
function saveProgress(){const v=state.current,p=state.player;if(!v||!p?.ready||itemSource(v)==='local')return;const t=p.time(),d=p.duration();if(Number.isFinite(t)&&t>2)data.progress[v.id]={time:t,duration:Number.isFinite(d)?d:0,at:Date.now()};const keys=Object.keys(data.progress).sort((a,b)=>data.progress[b].at-data.progress[a].at);for(const k of keys.slice(500))delete data.progress[k];persist();}
stopPlayer=function(){saveProgress();state.player?.destroy();state.player=null;$('#player').replaceChildren();state.current=null;state.loopA=null;state.loopB=null;$('#loopStatus').textContent='';$('#clearLoop').hidden=true;$('#transport').hidden=true;$('#playerError').textContent='';$('#chapters').replaceChildren();document.body.classList.remove('theater','focusmode');$('#focusMode').textContent='Focus mode';};
function playbackTick(t,d,paused){$('#playTime').textContent=stamp(t)+' / '+(Number.isFinite(d)?stamp(d):'Live');$('#playPause').textContent=paused?'Play':'Pause';if(document.activeElement!==$('#seek'))$('#seek').value=Number.isFinite(d)&&d>0?t/d*100:0;$('#seek').disabled=!Number.isFinite(d)||d<=0;if(state.loopA!==null&&state.loopB!==null&&t>=state.loopB)state.player.seek(state.loopA);if(state.sleepUntil&&Date.now()>=state.sleepUntil){state.player.pause();state.sleepUntil=0;$('#sleepTimer').value='0';toast('Sleep timer finished. Playback paused.');}if(Date.now()-progressSavedAt>10000){progressSavedAt=Date.now();saveProgress();}}
function createPlayer(){state.player?.destroy();$('#playerError').textContent='';const p=new PadhakuPlayer($('#player'),{onTick:playbackTick,onEnd:nextInQueue,onError:message=>{$('#playerError').textContent=message;},onReady:()=>{if(state.player!==p)return;$('#transport').hidden=false;$('#speed').hidden=false;$('#speed').innerHTML=p.rates().map(n=>`<option value="${n}" ${n===1?'selected':''}>${n}×</option>`).join('');$('#pip').hidden=p.kind!=='video';if(state.autoStartTarget===state.current?.id){state.autoStartTarget=null;p.play();}}});state.player=p;return p;}
embedded=function(){const v=state.current;if(!v||itemSource(v)!=='youtube')return;const resume=data.progress[v.id]?.time||0;createPlayer().embed(v.id,v.title,resume);$('#quality').hidden=true;$('#speed').hidden=true;$('#playState').textContent='YouTube player';$('#fallback').hidden=true;};
direct=function(index=0){const v=state.current,s=state.streams[index];if(!s||!v)return;const time=state.player?.time()||data.progress[v.id]?.time||0;const p=createPlayer();const url=s.url?.startsWith('blob:')&&v===sessionMedia?s.url:safe(s.url);if(!url){$('#playerError').textContent='Invalid media URL';return;}p.native(url,{audio:s.mimeType?.startsWith('audio/'),poster:safe(v.thumbnail),captions:v.captions||[],start:time});$('#quality').hidden=state.streams.length<2;$('#quality').innerHTML=state.streams.map((x,i)=>`<option value="${i}" ${index===i?'selected':''}>${esc(x.quality||x.mimeType||'Default')}</option>`).join('');$('#playState').textContent=itemSource(v)==='local'?'Local player':'Direct player';$('#fallback').hidden=true;};
const baseWatchMetadata=watchMetadata;
watchMetadata=function(v){baseWatchMetadata(v);const u=originalUrl(v);$('#sourceLink').href=u||'#';$('#sourceLink').hidden=!u;$('#subscribe').hidden=['local','direct'].includes(itemSource(v));$('#watchChannel').disabled=!v.channelUrl;$('#save').disabled=itemSource(v)==='local';$('#share').disabled=itemSource(v)==='local';$('#like').disabled=itemSource(v)==='local';$('#chapters').innerHTML=(v.chapters||[]).map(c=>`<button data-chapter="${Number(c.start)||0}">${stamp(c.start)} · ${esc(c.title)}</button>`).join('');$('#chapters').querySelectorAll('button').forEach(b=>b.onclick=()=>state.player?.seek(Number(b.dataset.chapter)));};
function renderNotes(){const v=state.current;if(!v)return;$('#notes').innerHTML=(data.notes[v.id]||[]).map(n=>`<article class="note"><button data-note-seek="${n.time}">${stamp(n.time)}</button><p>${esc(n.text)}</p><button data-note-remove="${esc(n.id)}" aria-label="Delete note">×</button></article>`).join('');$('#notes').querySelectorAll('[data-note-seek]').forEach(b=>b.onclick=()=>state.player?.seek(Number(b.dataset.noteSeek)));$('#notes').querySelectorAll('[data-note-remove]').forEach(b=>b.onclick=()=>{data.notes[v.id]=data.notes[v.id].filter(n=>n.id!==b.dataset.noteRemove);persist();renderNotes();});}
watch=async function(videoId,id){let v=known(videoId);const source=v?itemSource(v):inferSource(videoId)||'youtube';if(!v){if(source==='youtube'&&!/^[\w-]{11}$/.test(videoId)){$('#watchTitle').textContent='Invalid video link';return;}v={id:videoId,service:source,url:source==='youtube'?'https://www.youtube.com/watch?v='+videoId:videoId,title:'Loading…',channel:sourceNames[source],thumbnail:source==='youtube'?'https://i.ytimg.com/vi/'+videoId+'/hqdefault.jpg':''};}state.current=v;state.streams=[];watchMetadata(v);renderNotes();renderQueue();$('#comments').textContent='';$('#moreComments').hidden=true;$('#quality').hidden=true;$('#speed').hidden=true;$('#fallback').hidden=true;list($('#related'),state.seed.filter(x=>x.id!==v.id));
 if(source==='youtube'){embedded();$('#comments').textContent='YouTube comments are unavailable from this server.';const a=document.createElement('a');a.textContent='Read comments on YouTube ↗';a.href=originalUrl(v);a.target='_blank';a.rel='noopener';$('#comments').append(document.createElement('br'),a);}
 else if(source==='local'||source==='direct'){state.streams=[{url:v.mediaUrl,quality:'Original',mimeType:v.mimeType||'video/mp4'}];direct();$('#comments').textContent='Comments are not available for this media.';}
 else if(state.apiVersion<3){$('#playerError').textContent='This source needs the updated extractor backend. You can open the original source above.';}
 else{ $('#playState').textContent='Loading from '+sourceNames[source]+'…';try{const j=await api('/api/stream?service='+source+'&url='+encodeURIComponent(originalUrl(v)));if(id!==state.serial)return;v={...v,...j};state.current=v;state.streams=[...(v.streams||[]),...(v.audioStreams||[])].filter(s=>safe(s.url));if(v.hlsUrl)state.streams.push({url:v.hlsUrl,quality:'HLS · auto',mimeType:'application/vnd.apple.mpegurl'});watchMetadata(v);list($('#related'),v.related||[]);if(state.streams.length)direct();else $('#playerError').textContent='No browser-compatible stream was provided. Open the original source.';if(state.services.find(s=>s.id===source)?.comments)loadComments(videoId,id);else $('#comments').textContent='This source does not provide comments.';}catch(e){if(id===state.serial)$('#playerError').textContent=e.message;}}
 if(id!==state.serial)return;if(source!=='local'){data.history=[v,...data.history.filter(x=>x.id!==v.id)].slice(0,200);persist();}};
loadComments=async function(videoId,id,cursor=''){const v=state.current;if(!v||itemSource(v)==='youtube')return;try{const j=await api(cursor?'/api/more?cursor='+encodeURIComponent(cursor):'/api/comments?service='+itemSource(v)+'&url='+encodeURIComponent(originalUrl(v)));if(id!==state.serial)return;if(!cursor)$('#comments').replaceChildren();$('#comments').insertAdjacentHTML('beforeend',j.items.map(commentHTML).join(''));if(!j.items.length&&!cursor)$('#comments').textContent='No comments are available.';state.commentNext=j.next;$('#moreComments').hidden=!j.next;}catch(e){if(id===state.serial)$('#comments').textContent=e.message;}};
const originalRoute=route;
route=async function(){let r;try{r=routeData();}catch{location.hash='home';return;}if(['home','q','channel','remotePlaylist','kiosk','tab'].includes(r.name)){const id=++state.serial;stopPlayer();state.route=r.name;$('#browse').hidden=false;$('#watch').hidden=true;document.body.classList.remove('watchmode','navopen');$('#browse').classList.toggle('results',r.name==='q');$('#heading').textContent=r.name==='q'?'Search results':'';$('#channelHeader').replaceChildren();$('#grid').replaceChildren();$('#loadMore').hidden=true;$('#clearHistory').hidden=true;$('#notice').textContent='Loading…';$('#chips').hidden=!['home','q'].includes(r.name);nav();chips();banner();window.scrollTo({top:0});let path='';
 if(['home','q'].includes(r.name)){const q=r.name==='q'?r.value:state.source==='youtube'?'science technology education India':'science';$('#query').value=r.name==='q'?r.value:'';if(!state.api){const items=r.name==='home'?state.seed:state.seed.filter(v=>(v.title+' '+v.channel+' '+v.category).toLowerCase().includes(q.toLowerCase()));setItems(items);$('#notice').textContent='';return;}path='/api/search?q='+encodeURIComponent(q)+'&service='+state.source+(state.apiVersion>=3?'&filter='+encodeURIComponent(state.filter)+'&sort='+encodeURIComponent(state.sort):'');}
 else if(r.name==='channel'||r.name==='remotePlaylist'){const source=inferSource(r.value)||state.source;if(state.apiVersion<3&&(source!=='youtube'||r.name==='remotePlaylist')){$('#notice').textContent='This feature needs the updated extractor backend.';return;}state.source=source;sourceControls();path='/api/'+(r.name==='remotePlaylist'?'playlist':'channel')+'?service='+source+'&url='+encodeURIComponent(r.value);}
 else if(r.name==='kiosk')path='/api/kiosk?service='+state.source+'&id='+encodeURIComponent(r.value);
 else path='/api/tab?token='+encodeURIComponent(r.value);
 try{const j=await api(path);if(id!==state.serial)return;$('#notice').textContent='';state.connected=true;banner();setItems(j.items,j.next);if(r.name==='channel'){const c=j;$('#channelHeader').innerHTML=`${safe(c.banner)?`<div class="channelbanner"><img src="${esc(c.banner)}" alt=""></div>`:''}<div class="channelhead">${avatar(c)}<div><h1>${esc(c.name)}</h1><p>${count(c.subscribers)} subscribers</p><p class="about">${esc(c.description)}</p><button class="subscribe" id="channelSubscribe">${data.subs.some(s=>s.url===c.url)?'Subscribed':'Subscribe'}</button>${safe(c.feedUrl)?` <a href="${esc(c.feedUrl)}" target="_blank" rel="noopener">RSS feed ↗</a>`:''}</div></div><div class="channel-tabs">${(c.tabs||[]).map(t=>`<button data-tab="${esc(t.token)}">${esc(t.name||'Videos')}</button>`).join('')}</div>`;$('#channelSubscribe').onclick=()=>{toggleSub({url:c.url,name:c.name,avatar:c.avatar,service:state.source});$('#channelSubscribe').textContent=data.subs.some(s=>s.url===c.url)?'Subscribed':'Subscribe';};$('#channelHeader').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>location.hash='tab='+encodeURIComponent(b.dataset.tab));}
 if(r.name==='remotePlaylist'){$('#heading').textContent=j.title;const b=document.createElement('button');b.className='outline';b.textContent='Add loaded videos to queue';b.onclick=()=>{for(const v of state.items.filter(v=>!v.kind||v.kind==='video'))if(!data.queue.some(x=>x.id===v.id))data.queue.push(v);persist();renderQueue();toast('Videos added to queue');};$('#channelHeader').append(b);}}
 catch(e){if(id===state.serial){$('#notice').textContent=e.message;$('#grid').innerHTML=empty('Couldn’t load this source','Try another source or open Settings.');}}return;}
 await originalRoute();if(r.name==='playlist'){const p=data.playlists.find(p=>p.id===r.value);if(p){const controls=document.createElement('div');controls.className='collection-actions';controls.innerHTML='<button class="outline" id="queuePlaylist">Queue all</button><button class="outline" id="renamePlaylist">Rename</button><button class="outline" id="deletePlaylist">Delete playlist</button>';$('#channelHeader').append(controls);$('#queuePlaylist').onclick=()=>{data.queue=[...p.videos];persist();renderQueue();if(data.queue[0]){state.autoStartTarget=data.queue[0].id;location.hash=watchHash(data.queue[0]);}};$('#renamePlaylist').onclick=()=>{const n=prompt('Playlist name',p.name);if(n?.trim()){p.name=n.trim().slice(0,60);persist();route();}};$('#deletePlaylist').onclick=()=>{if(confirm('Delete this local playlist? Videos will not be deleted.')){data.playlists=data.playlists.filter(x=>x!==p);persist();location.hash='playlists';}};}}
};
