function sourceControls(){const available=state.apiVersion>=3?state.services:[{id:'youtube',name:'YouTube'}];if(!available.some(s=>s.id===state.source))state.source='youtube';$('#sourceSelect').innerHTML=available.map(s=>`<option value="${esc(s.id)}" ${s.id===state.source?'selected':''}>${esc(s.name)}</option>`).join('');const s=available.find(s=>s.id===state.source)||{},filters=s.filters||[],sorts=s.sorts||[];$('#filterLabel').hidden=!filters.length;$('#sortLabel').hidden=!sorts.length;$('#filterSelect').innerHTML='<option value="">All</option>'+filters.map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('');$('#filterSelect').value=state.filter;$('#sortSelect').innerHTML='<option value="">Default</option>'+sorts.map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('');$('#sortSelect').value=state.sort;$('#kioskSelect').hidden=!s.kiosks?.length;$('#kioskSelect').innerHTML='<option value="">Explore feeds</option>'+(s.kiosks||[]).map(f=>`<option value="${esc(f)}">${esc(f)}</option>`).join('');$('#sourceStatus').textContent=state.apiVersion>=3?'Powered by NewPipeExtractor':'Multi-source browsing needs backend v3';}
const originalCheckConnection=checkConnection;
checkConnection=async function(base=state.api){const j=await originalCheckConnection(base);state.apiVersion=j.apiVersion||2;if(state.apiVersion>=3){const c=await api('/api/services',base);state.services=c.services||[];const saved=localStorage.getItem('pt-source');if(state.services.some(s=>s.id===saved))state.source=saved;}sourceControls();return j;};
parseSearch=function(q){try{const u=new URL(q),s=inferSource(q);if(s==='youtube'){if(u.searchParams.get('list')&&!u.searchParams.get('v'))return 'remotePlaylist='+encodeURIComponent('https://www.youtube.com/playlist?list='+u.searchParams.get('list'));const id=u.searchParams.get('v')||(u.hostname==='youtu.be'?u.pathname.slice(1):u.pathname.split('/')[2]);if(id&&/^[\w-]{11}$/.test(id))return 'watch='+id;if(/^\/(channel\/|@|c\/|user\/)/.test(u.pathname))return 'channel='+encodeURIComponent(u.origin+u.pathname.replace(/\/$/,''));}else if(s)return 'watch='+encodeURIComponent(q);}catch{}return 'q='+encodeURIComponent(q);};
$('#sourceSelect').onchange=()=>{state.source=$('#sourceSelect').value;state.filter='';state.sort='';localStorage.setItem('pt-source',state.source);sourceControls();route();};$('#filterSelect').onchange=()=>{state.filter=$('#filterSelect').value;route();};$('#sortSelect').onchange=()=>{state.sort=$('#sortSelect').value;route();};$('#kioskSelect').onchange=()=>{if($('#kioskSelect').value)location.hash='kiosk='+encodeURIComponent($('#kioskSelect').value);};
$('#query').addEventListener('input',()=>{clearTimeout(suggestTimer);$('#suggestions').replaceChildren();const q=$('#query').value.trim();if(state.apiVersion<3||q.length<2||q.startsWith('https://'))return;suggestTimer=setTimeout(async()=>{try{const j=await api('/api/suggest?service='+state.source+'&q='+encodeURIComponent(q));if($('#query').value.trim()===q)$('#suggestions').innerHTML=j.items.slice(0,10).map(s=>`<option value="${esc(s)}"></option>`).join('');}catch{}},450);});
$('#playPause').onclick=()=>{const p=state.player;if(p)p.paused()?p.play():p.pause();};$('#back10').onclick=()=>state.player?.seek(state.player.time()-10);$('#forward10').onclick=()=>state.player?.seek(state.player.time()+10);$('#seek').oninput=()=>{const p=state.player;if(p)p.seek(Number($('#seek').value)/100*p.duration());};$('#volume').oninput=()=>state.player?.volume(Number($('#volume').value));$('#speed').onchange=()=>state.player?.speed(Number($('#speed').value));$('#pip').onclick=async()=>{try{await state.player?.pip();}catch(e){toast(e.message);}};$('#fullscreen').onclick=async()=>{try{await state.player?.fullscreen();}catch(e){toast('Full screen is unavailable in this browser.');}};
$('#focusMode').onclick=()=>{const on=document.body.classList.toggle('focusmode');$('#focusMode').textContent=on?'Exit focus':'Focus mode';};$('#markA').onclick=()=>{if(!state.player?.ready){toast('Start the player before setting a loop.');return;}state.loopA=state.player.time();state.loopB=null;$('#clearLoop').hidden=false;$('#loopStatus').textContent='A '+stamp(state.loopA)+' · now choose B';};$('#markB').onclick=()=>{const t=state.player?.time()||0;if(state.loopA===null||t<=state.loopA+.5){toast('Set A first, then choose B at least one second later.');return;}state.loopB=t;$('#loopStatus').textContent='Loop '+stamp(state.loopA)+'–'+stamp(t);state.player.seek(state.loopA);};$('#clearLoop').onclick=()=>{state.loopA=null;state.loopB=null;$('#clearLoop').hidden=true;$('#loopStatus').textContent='';};$('#sleepTimer').onchange=()=>{state.sleepUntil=Number($('#sleepTimer').value)?Date.now()+Number($('#sleepTimer').value)*60000:0;toast(state.sleepUntil?'Playback will pause after '+$('#sleepTimer').value+' minutes':'Sleep timer off');};
$('#noteForm').onsubmit=e=>{e.preventDefault();const v=state.current,text=$('#noteText').value.trim();if(!v||!text)return;const notes=data.notes[v.id]||[];if(notes.length>=200){toast('This video already has 200 notes. Export them before adding more.');return;}notes.push({id:crypto.randomUUID(),time:Math.floor(state.player?.time()||0),text});data.notes[v.id]=notes;persist();$('#noteText').value='';renderNotes();};$('#exportNotes').onclick=()=>{const v=state.current;if(!v)return;downloadable('padhakutube-notes.txt',v.title+'\n'+originalUrl(v)+'\n\n'+(data.notes[v.id]||[]).map(n=>'['+stamp(n.time)+'] '+n.text).join('\n\n'),'text/plain');};$('#autoNext').checked=state.autoNext;$('#autoNext').onchange=()=>{state.autoNext=$('#autoNext').checked;localStorage.setItem('pt-autonext',String(state.autoNext));};$('#clearQueue').onclick=()=>{data.queue=[];persist();renderQueue();};
$('#subscribe').onclick=()=>state.current&&toggleSub({url:state.current.channelUrl,name:state.current.channel,avatar:state.current.avatar,service:itemSource(state.current)});$('#share').onclick=()=>{const v=state.current;if(!v)return;const u=originalUrl(v);if(!u){toast('Local files cannot be shared with a link.');return;}$('#shareUrl').value=u;$('#original').href=u;$('#original').textContent='Open original ↗';$('#shareDialog').showModal();};
$('#disconnect').onclick=()=>{state.api='';state.connected=false;localStorage.setItem('pt-api','');localStorage.setItem('pt-offline','true');$('#connectionStatus').textContent='Disconnected. Showing the curated collection.';route();};const connectOld=$('#connect').onclick;$('#connect').onclick=async()=>{await connectOld();if(state.connected)localStorage.removeItem('pt-offline');};
function openSessionMedia(v){sessionMedia=v;$('#mediaDialog').close();if(location.hash===watchHash(v))route();else location.hash=watchHash(v);}
$('#openMedia').onclick=()=>$('#mediaDialog').showModal();$('#mediaForm').onsubmit=e=>{e.preventDefault();const u=safe($('#mediaUrl').value.trim());if(!u){toast('Enter a valid HTTPS media URL.');return;}const audio=/\.(mp3|m4a|ogg|wav)(\?|$)/i.test(u);openSessionMedia({id:u,url:u,mediaUrl:u,service:'direct',title:new URL(u).pathname.split('/').pop()||'Direct media',channel:'Your media',mimeType:audio?'audio/mpeg':'video/mp4'});};$('#mediaFile').onchange=()=>{const f=$('#mediaFile').files[0];if(!f)return;if(blobUrl)URL.revokeObjectURL(blobUrl);blobUrl=URL.createObjectURL(f);openSessionMedia({id:'local:'+f.name+':'+f.size,service:'local',title:f.name,channel:'On this device',mediaUrl:blobUrl,mimeType:f.type});};
$('#exportData').onclick=()=>downloadable('padhakutube-backup.json',JSON.stringify({app:'PadhakuTube',version:1,createdAt:new Date().toISOString(),data},null,2));
function validVideo(v){return v&&typeof v.id==='string'&&v.id.length<2000&&typeof v.title==='string'&&v.title.length<2000&&(!!safe(v.id)||/^[\w-]{11}$/.test(v.id));}
function validateBackup(x){if(x.app!=='PadhakuTube'||x.version!==1||!x.data)throw Error('This is not a PadhakuTube backup.');const d=x.data,o={};for(const k of ['saved','history','liked','queue']){if(!Array.isArray(d[k])||d[k].length>3000||!d[k].every(validVideo))throw Error('Invalid '+k+' collection');o[k]=d[k];}if(!Array.isArray(d.playlists)||d.playlists.length>200||!d.playlists.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&p.name.length<=60&&Array.isArray(p.videos)&&p.videos.length<=3000&&p.videos.every(validVideo)))throw Error('Invalid playlists');o.playlists=d.playlists;if(!Array.isArray(d.subs)||d.subs.length>2000||!d.subs.every(s=>safe(s.url)&&typeof s.name==='string'))throw Error('Invalid subscriptions');o.subs=d.subs;o.notes={};for(const [id,ns] of Object.entries(d.notes||{})){if(['__proto__','constructor','prototype'].includes(id)||!Array.isArray(ns)||ns.length>200||!ns.every(n=>typeof n.id==='string'&&typeof n.text==='string'&&n.text.length<=4000&&Number.isFinite(n.time)&&n.time>=0))throw Error('Invalid notes');o.notes[id]=ns;}o.progress={};for(const [id,p] of Object.entries(d.progress||{})){if(['__proto__','constructor','prototype'].includes(id)||!Number.isFinite(p.time)||p.time<0)throw Error('Invalid playback progress');o.progress[id]=p;}return o;}
$('#importData').onchange=async()=>{try{const f=$('#importData').files[0];if(!f)return;if(f.size>5000000)throw Error('Backup must be smaller than 5 MB.');const d=validateBackup(JSON.parse(await f.text()));if(!confirm('Replace this browser’s library and notes with the selected backup?'))return;stopPlayer();Object.assign(data,d);persist();$('#dataStatus').textContent='Backup restored.';route();}catch(e){$('#dataStatus').textContent=e.message;}finally{$('#importData').value='';}};
const serviceIds={0:'youtube',1:'soundcloud',2:'mediaccc',3:'peertube',4:'bandcamp'};
$('#importSubs').onchange=async()=>{try{const f=$('#importSubs').files[0];if(!f)return;if(f.size>2000000)throw Error('Subscription file is too large.');const j=JSON.parse(await f.text());if(!Array.isArray(j.subscriptions))throw Error('Choose a NewPipe subscriptions JSON export.');let added=0;for(const s of j.subscriptions.slice(0,2000)){const source=serviceIds[s.service_id];if(!source||!safe(s.url)||inferSource(s.url)!==source||typeof s.name!=='string')continue;if(!data.subs.some(x=>x.url===s.url)){data.subs.push({url:s.url,name:s.name.slice(0,200),service:source});added++;}}persist();nav();$('#dataStatus').textContent=added+' subscriptions imported.';}catch(e){$('#dataStatus').textContent=e.message;}finally{$('#importSubs').value='';}};$('#exportSubs').onclick=()=>downloadable('newpipe-subscriptions.json',JSON.stringify({app_version:'PadhakuTube',app_version_int:1,subscriptions:data.subs.map(s=>({service_id:Number(Object.keys(serviceIds).find(k=>serviceIds[k]===(s.service||inferSource(s.url)||'youtube'))),url:s.url,name:s.name}))},null,2));
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;if(state.route!=='watch'||!state.player?.ready)return;const p=state.player;if(['k',' ','j','l','ArrowLeft','ArrowRight','f'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key==='k'||e.key===' ')p.paused()?p.play():p.pause();else if(e.key==='j'||e.key==='ArrowLeft')p.seek(p.time()-10);else if(e.key==='l'||e.key==='ArrowRight')p.seek(p.time()+10);else p.fullscreen();}},true);
window.addEventListener('pagehide',saveProgress);if(localStorage.getItem('pt-offline')==='true')state.api='';sourceControls();renderQueue();

if(state.api)checkConnection().then(()=>{state.connected=true;banner();}).catch(()=>{});
